reference_solution:
def kth_expanded_character(s,k):
    words=s.split(' ')
    for word_index,word in enumerate(words):
        length=len(word)*(len(word)+1)//2
        if k<length:
            used=0
            for index,character in enumerate(word):
                used+=index+1
                if k<used:return character
        k-=length
        if word_index+1<len(words):
            if k==0:return ' '
            k-=1

